using InovaGed.Environment.Doctor.Quality; namespace InovaGed.Environment.Doctor.Checks;
public sealed class LayoutQualityCheck:IQualityCheck { public string Name=>"Layout"; public Task<IReadOnlyList<QualityFinding>> RunAsync(QualityContext c,CancellationToken ct){var r=new List<QualityFinding>(); CheckText("InovaGed.Web/Views/Shared/_Layout.cshtml","RenderSectionAsync(\"Styles\"","seção Styles");CheckText("InovaGed.Web/Views/Shared/_Layout.cshtml","RenderSectionAsync(\"Scripts\"","seção Scripts");CheckText("InovaGed.Web/Views/Administration/Index.cshtml","@section Styles","CSS da Administração");CheckText("InovaGed.Web/Views/Labels/PrintWizard.cshtml","@section Styles","CSS do PrintWizard"); foreach(var f in new[]{"InovaGed.Web/wwwroot/css/pages/administration.css","InovaGed.Web/wwwroot/css/pages/labels-print-wizard.css"}) r.Add(File.Exists(Path.Combine(c.Root,f))?new(Name,QualityStatus.Pass,$"Asset presente: {f}",Resource:f):new(Name,QualityStatus.Fail,$"Asset obrigatório ausente: {f}","Layout sem estilos.","Criar e referenciar o CSS.",Resource:f)); return Task.FromResult<IReadOnlyList<QualityFinding>>(r); void CheckText(string f,string needle,string label){var p=Path.Combine(c.Root,f);r.Add(File.Exists(p)&&File.ReadAllText(p).Contains(needle,StringComparison.Ordinal)?new(Name,QualityStatus.Pass,$"{label} configurado.",Resource:f):new(Name,QualityStatus.Fail,$"{label} não configurado em {f}.","Layout incompleto.","Adicionar a seção requerida.",Resource:f));}}
}
